usage:
Enable the Better Auth Stripe plugin, then feed it from the Stripe client and open the portal on manage:

```ts
const { data: subs } = useQuery({ queryKey: ['subs'], queryFn: () => client.subscription.list() })
const active = subs?.find((s) => s.status === 'active' || s.status === 'trialing')
const portal = useMutation({ mutationFn: () => client.subscription.billingPortal({ returnUrl: '/app/billing' }) })
<SubscriptionStatusCard planName={asI18n(active?.plan)} status={active?.status ?? 'none'} renewsOn={active?.periodEnd?.toLocaleDateString()} onManage={portal.mutate} />
```
